<script setup lang="ts">
defineProps<{blocks:any[];depth?:number}>()
function move(blocks:any[],i:number,dir:number){const j=i+dir;if(j>=0&&j<blocks.length)[blocks[i],blocks[j]]=[blocks[j],blocks[i]]}
function duplicate(blocks:any[],i:number){blocks.splice(i+1,0,JSON.parse(JSON.stringify(blocks[i])))}
</script>
<template><div class="blocks"><div v-for="(b,i) in blocks" :key="i" class="block-editor"><div class="block-tools"><span class="block-number">{{i+1}}</span><strong>{{b.repeat?'Ripetizione':'Blocco'}}</strong><div class="actions"><button type="button" class="icon-button" @click="move(blocks,i,-1)" :disabled="i===0" title="Sposta su">↑</button><button type="button" class="icon-button" @click="move(blocks,i,1)" :disabled="i===blocks.length-1" title="Sposta giù">↓</button><button type="button" class="icon-button" @click="duplicate(blocks,i)" title="Duplica">⧉</button><button type="button" class="icon-button" @click="blocks.splice(i,1)" title="Rimuovi">×</button></div></div><template v-if="b.repeat"><label>Numero ripetizioni<input type="number" min="1" max="1000" v-model.number="b.repeat"></label><BlockEditor :blocks="b.blocks" :depth="(depth||0)+1"/></template><template v-else><div class="form-grid"><label>Durata · secondi<input type="number" min="1" step="1" v-model.number="b.duration_s"></label><label>Potenza target<select v-model="b.target.kind"><option value="constant">Valore in watt</option><option value="range">Intervallo in watt</option></select></label><label v-if="b.target.kind==='constant'">Watt<input type="number" min="0" v-model.number="b.target.watts"></label><template v-else><label>Min · W<input type="number" min="0" v-model.number="b.target.low_w"></label><label>Max · W<input type="number" min="0" v-model.number="b.target.high_w"></label></template></div><template v-if="b.target.kind==='range'"><label>Come risolvere questo range<select v-model="b.choice_mode"><option value="">Scegli esplicitamente…</option><option value="center">Valore centrale</option><option value="profile">Profilo definito</option><option value="scenarios">Scenari distinti</option></select></label><label v-if="b.choice_mode==='profile'">Punti [tempo_s, watt] · includere 0 e durata<textarea v-model="b.choice_json" placeholder="[[0,180],[300,220]]"></textarea></label><label v-if="b.choice_mode==='scenarios'">Scenari nominati · stessi nomi in tutti i range<textarea v-model="b.choice_json" placeholder='{"facile":180,"intenso":220}'></textarea></label></template></template></div><div class="actions"><button type="button" class="secondary" @click="blocks.push({duration_s:300,target:{kind:'constant',watts:150},choice_mode:''})">+ Blocco</button><button v-if="(depth||0)<2" type="button" class="secondary" @click="blocks.push({repeat:3,blocks:[{duration_s:180,target:{kind:'constant',watts:200}},{duration_s:120,target:{kind:'constant',watts:100}}]})">+ Ripetizione</button></div></div></template>
